ALTER TABLE public.fee_proposals ADD COLUMN IF NOT EXISTS accepted_snapshot_id uuid REFERENCES public.psa_proposal_snapshots(id), ADD COLUMN IF NOT EXISTS acceptance_date date, ADD COLUMN IF NOT EXISTS acceptance_note text, ADD COLUMN IF NOT EXISTS acceptance_attachment_path text, ADD COLUMN IF NOT EXISTS acceptance_actor uuid, ADD COLUMN IF NOT EXISTS accepted_content_hash text;
CREATE OR REPLACE FUNCTION public.crm_quote_content_hash(_quote uuid) RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT md5(jsonb_build_object('quote',(select to_jsonb(q)-ARRAY['quote_status','is_locked','locked_at','locked_project_id','pm_project_id','approved_at','signed_at','signed_method','signed_notes','updated_at','accepted_snapshot_id','acceptance_date','acceptance_note','acceptance_attachment_path','acceptance_actor','accepted_content_hash'] from fee_proposals q where id=_quote),'stages',(select jsonb_agg(to_jsonb(s) order by s.id) from quote_stages s where s.quote_id=_quote),'payments',(select jsonb_agg(to_jsonb(p) order by p.id) from quote_payment_schedule_items p where p.quote_id=_quote),'blocks',(select jsonb_agg(to_jsonb(b) order by b.id) from psa_proposal_blocks b join psa_proposals p on p.id=b.proposal_id where p.quote_id=_quote))::text) $$;
CREATE OR REPLACE FUNCTION public.crm_quote_lifecycle(_quote uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE v_quote fee_proposals; v_sent record; v_state text; v_missing jsonb:='[]';
BEGIN SELECT * INTO v_quote FROM fee_proposals WHERE id=_quote; IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;
 SELECT s.id,s.rev_number,s.created_at,p.id proposal_id,s.pdf_filename INTO v_sent FROM psa_proposal_snapshots s JOIN psa_proposals p ON p.id=s.proposal_id WHERE p.quote_id=_quote AND s.kind='sent' ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
 v_state:=CASE WHEN v_quote.pm_project_id IS NOT NULL THEN 'converted' WHEN v_quote.quote_status='rejected' THEN 'lost' WHEN v_quote.quote_status='approved' AND v_quote.signed_at IS NOT NULL THEN 'signed' WHEN v_quote.quote_status='approved' THEN 'approved' WHEN v_quote.quote_status='sent' OR v_sent.id IS NOT NULL OR EXISTS(SELECT 1 FROM psa_proposals WHERE quote_id=_quote AND status='sent') THEN 'sent' ELSE 'draft' END;
 IF v_quote.company_id IS NULL THEN v_missing:=v_missing||jsonb_build_array('client'); END IF;
 IF v_quote.accepted_snapshot_id IS NULL THEN v_missing:=v_missing||jsonb_build_array('revision'); END IF;
 IF NOT EXISTS(SELECT 1 FROM quote_stages WHERE quote_id=_quote) THEN v_missing:=v_missing||jsonb_build_array('gantt'); END IF;
 RETURN jsonb_build_object('state',v_state,'quoteId',_quote,'projectId',v_quote.pm_project_id,'proposalId',v_sent.proposal_id,'latestSentSnapshotId',v_sent.id,'latestSentRevision',v_sent.rev_number,'acceptedSnapshotId',v_quote.accepted_snapshot_id,'acceptanceDate',v_quote.acceptance_date,'missing',v_missing); END $$;
REVOKE ALL ON FUNCTION public.crm_quote_lifecycle(uuid), public.crm_quote_content_hash(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_quote_lifecycle(uuid), public.crm_quote_content_hash(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.crm_quote_transition(_quote uuid,_action text,_date date DEFAULT NULL,_note text DEFAULT NULL,_snapshot uuid DEFAULT NULL,_attachment text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE v_quote fee_proposals; v_state text;
BEGIN IF auth.uid() IS NULL OR NOT is_psa_staff() OR NOT (has_role(auth.uid(),'admin') OR has_permission(auth.uid(),'crm.pipeline')) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_quote FROM fee_proposals WHERE id=_quote FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF; v_state:=crm_quote_lifecycle(_quote)->>'state';
 IF _action='send' AND v_state='draft' THEN UPDATE fee_proposals SET quote_status='sent' WHERE id=_quote;
 ELSIF _action='accept' AND v_state='sent' THEN IF _date IS NULL THEN RAISE EXCEPTION 'Acceptance date required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM psa_proposal_snapshots s JOIN psa_proposals p ON p.id=s.proposal_id WHERE s.id=_snapshot AND p.quote_id=_quote AND s.kind='sent') THEN RAISE EXCEPTION 'Accepted revision required'; END IF;
 IF _attachment IS NOT NULL AND _attachment NOT LIKE _quote::text||'/acceptance/%' THEN RAISE EXCEPTION 'Invalid acceptance attachment'; END IF;
 UPDATE fee_proposals SET quote_status='approved',approved_at=now(),acceptance_date=_date,acceptance_note=nullif(btrim(_note),''),accepted_snapshot_id=_snapshot,acceptance_attachment_path=_attachment,acceptance_actor=auth.uid() WHERE id=_quote;
 UPDATE fee_proposals SET accepted_content_hash=crm_quote_content_hash(_quote) WHERE id=_quote;
 ELSIF _action='sign' AND v_state='approved' THEN IF _date IS NULL THEN RAISE EXCEPTION 'Signature date required'; END IF;
 UPDATE fee_proposals SET signed_at=_date::timestamp AT TIME ZONE 'Europe/Lisbon',signed_method='manual',signed_notes=nullif(btrim(_note),'') WHERE id=_quote;
 ELSIF _action='lose' AND v_state IN ('draft','sent','approved','signed') THEN UPDATE fee_proposals SET quote_status='rejected' WHERE id=_quote;
 ELSE RAISE EXCEPTION 'Invalid quote lifecycle transition'; END IF; RETURN crm_quote_lifecycle(_quote); END $$;
REVOKE ALL ON FUNCTION public.crm_quote_transition(uuid,text,date,text,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_quote_transition(uuid,text,date,text,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.crm_quote_opportunity_stage(_opportunity uuid) RETURNS public.crm_opportunity_stage LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN bool_or(q.pm_project_id IS NOT NULL OR q.quote_status='approved') THEN 'won' WHEN bool_or(q.quote_status='sent' OR EXISTS(SELECT 1 FROM psa_proposals p WHERE p.quote_id=q.id AND p.status='sent')) THEN 'negotiation' WHEN bool_and(q.quote_status='rejected') THEN 'lost' ELSE 'proposal' END::crm_opportunity_stage FROM fee_proposals q WHERE q.opportunity_id=_opportunity AND q.archived_at IS NULL AND q.deleted_at IS NULL HAVING count(*)>0 $$;
CREATE OR REPLACE FUNCTION public.sync_opportunity_stage_from_quote() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_stage crm_opportunity_stage; BEGIN v_id:=COALESCE(NEW.opportunity_id,OLD.opportunity_id); v_stage:=crm_quote_opportunity_stage(v_id); IF v_stage IS NOT NULL THEN UPDATE crm_opportunities SET stage=v_stage WHERE id=v_id AND stage IS DISTINCT FROM v_stage; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE OR REPLACE FUNCTION public.crm_opportunity_quote_stage_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_stage crm_opportunity_stage; BEGIN v_stage:=crm_quote_opportunity_stage(NEW.id); IF v_stage IS NOT NULL THEN NEW.stage:=v_stage; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_opportunity_quote_stage_guard BEFORE UPDATE OF stage ON public.crm_opportunities FOR EACH ROW EXECUTE FUNCTION public.crm_opportunity_quote_stage_guard();
CREATE OR REPLACE FUNCTION public.crm_proposal_lifecycle_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.quote_id IS NOT NULL THEN IF NEW.status='sent' THEN UPDATE fee_proposals SET quote_status='sent' WHERE id=NEW.quote_id AND quote_status='draft' AND pm_project_id IS NULL; ELSIF NEW.status='declined' THEN UPDATE fee_proposals SET quote_status='rejected' WHERE id=NEW.quote_id AND pm_project_id IS NULL; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_proposal_lifecycle_sync AFTER UPDATE OF status,sent_at ON public.psa_proposals FOR EACH ROW EXECUTE FUNCTION public.crm_proposal_lifecycle_sync();
DO $patch$ DECLARE v_definition text; v_anchor text; BEGIN SELECT pg_get_functiondef('public.pm_convert_relative_quote(uuid,date,text)'::regprocedure) INTO v_definition; v_anchor:='preview:=pm_quote_conversion_preview(_quote,_start);'; IF strpos(v_definition,v_anchor)=0 THEN RAISE EXCEPTION 'Conversion guard anchor missing'; END IF; v_definition:=replace(v_definition,v_anchor,'IF q.company_id IS NULL THEN RAISE EXCEPTION ''Client company required''; END IF; IF q.accepted_snapshot_id IS NULL THEN RAISE EXCEPTION ''Accepted revision required''; END IF; IF q.accepted_content_hash IS DISTINCT FROM crm_quote_content_hash(_quote) THEN RAISE EXCEPTION ''Accepted content changed''; END IF; IF NOT EXISTS(SELECT 1 FROM quote_stages WHERE quote_id=_quote) THEN RAISE EXCEPTION ''Gantt required''; END IF; '||v_anchor); EXECUTE v_definition; END $patch$;
REVOKE ALL ON FUNCTION public.crm_quote_opportunity_stage(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_quote_opportunity_stage(uuid) TO authenticated,service_role;